// reportHeader is the first line of the daily report, e.g. "Report for 2026-03-05".
function reportHeader(date) {
  return `Report for ${date.getUTCFullYear()}-${date.getUTCMonth() + 1}-${date.getUTCDate()}`;
}

module.exports = { reportHeader };
// reminderSubject is the subject line of the payment reminder email.
function reminderSubject(invoiceId, due) {
  const when = [due.getUTCFullYear(), due.getUTCMonth() + 1, due.getUTCDate()].join('-');
  return `Invoice ${invoiceId} is due on ${when}`;
}

module.exports = { reminderSubject };
// toCsvRow turns an order into one CSV line: id,date,amount
function toCsvRow(order) {
  const d = order.placedAt;
  const y = d.getUTCFullYear();
  const m = d.getUTCMonth() + 1;
  const day = d.getUTCDate();
  return [order.id, y + '-' + m + '-' + day, order.amount].join(',');
}

module.exports = { toCsvRow };
